<?php
require_once __DIR__.'/config/db.php';require_once __DIR__.'/config/auth.php';require_role('studente');
$pageTitle='Voti';$active='voti';$id=$_SESSION['user_id'];$materia=(int)($_GET['materia']??0);
$stmt=$pdo->prepare('SELECT DISTINCT m.id,m.nome FROM voti v JOIN materie m ON m.id=v.materia_id WHERE v.studente_id=? ORDER BY m.nome');$stmt->execute([$id]);$materie=$stmt->fetchAll();
$sql='SELECT v.voto,v.tipo,v.data,m.nome materia FROM voti v JOIN materie m ON m.id=v.materia_id WHERE v.studente_id=?';$params=[$id];if($materia){$sql.=' AND v.materia_id=?';$params[]=$materia;}$sql.=' ORDER BY v.data DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
$stmt=$pdo->prepare('SELECT m.nome,ROUND(AVG(v.voto),1) media,COUNT(*) totale FROM voti v JOIN materie m ON m.id=v.materia_id WHERE v.studente_id=? GROUP BY m.id,m.nome ORDER BY m.nome');$stmt->execute([$id]);$medie=$stmt->fetchAll();
$generale=$rows?round(array_sum(array_column($rows,'voto'))/count($rows),1):null;
require __DIR__.'/includes/header.php';require __DIR__.'/includes/sidebar.php';?><main class="main"><header class="topbar"><h1>Voti</h1><div class="user-menu"><a href="logout.php">Esci</a></div></header><section class="content"><div class="page-head"><h2>Valutazioni</h2><p>Consulta voti, medie e andamento per materia.</p></div><form method="get" class="card form-card"><div class="field"><label>Filtra per materia</label><select name="materia"><option value="0">Tutte le materie</option><?php foreach($materie as $m): ?><option value="<?=$m['id']?>" <?=$materia===$m['id']?'selected':''?>><?=e($m['nome'])?></option><?php endforeach?></select></div><button class="btn">Applica filtro</button></form><div class="grid section"><article class="card"><div class="stat-label">Media generale</div><div class="stat-number"><?=$generale??'N/D'?></div><div class="muted">Su <?=count($rows)?> valutazioni visualizzate</div></article><?php foreach($medie as $m): ?><article class="card"><div class="stat-label"><?=e($m['nome'])?></div><div class="stat-number"><?=$m['media']?></div><div class="muted"><?=$m['totale']?> valutazioni</div></article><?php endforeach?></div><div class="section"><h3>Elenco voti</h3><div class="table-wrap"><table><thead><tr><th>Data</th><th>Materia</th><th>Tipo</th><th>Voto</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="4" class="empty">Nessun voto disponibile.</td></tr><?php endif;foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['data']))?></td><td><?=e($r['materia'])?></td><td><?=e($r['tipo'])?></td><td class="<?=$r['voto']>=6?'good':'bad'?>"><?=$r['voto']?></td></tr><?php endforeach?></tbody></table></div></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>